mapper.insert:
insert into chatmessage (
    id, session_id, sender_id, receiver_id, type, content, read_status,
    read_time, create_time, update_time, create_user, update_user
) values (
    #{id}, #{sessionId}, #{senderId}, #{receiverId}, #{type}, #{content}, #{readStatus},
    #{readTime}, #{createTime}, #{updateTime}, #{createUser}, #{updateUser}
)

mapper.select:
select cm.id
from chatmessage cm
where cm.session_id = #{sessionId}
  and cm.receiver_id = #{receiverId}
  and cm.read_status = 0
order by cm.create_time asc, cm.id asc

mapper.update:
update chatmessage
set read_status = 1,
    read_time = #{readTime},
    update_time = #{readTime},
    update_user = #{receiverId}
where session_id = #{sessionId}
  and receiver_id = #{receiverId}
  and read_status = 0
